#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
int jumps=0,curEnd=0;long long farthest=0;
for(int i=0;i<n-1;++i){
farthest=max(farthest,(long long)i+a[i]);
if(i==curEnd){++jumps;curEnd=farthest;}}
printf("%d\n",jumps);return 0;}

